        content=msg.content, tool_calls=tool_calls, finish_reason=choice.finish_reason or "stop",
        usage={"prompt_tokens": u.prompt_tokens, "completion_tokens": u.completion_tokens, "total_tokens": u.total_tokens} if u else {},
