async def start(self) -> None:
    """Start the Discord gateway connection."""
    if not self.config.token:
        logger.error("Discord bot token not configured")
        return

    self._running = True
    self._http = httpx.AsyncClient(timeout=30.0)

    while self._running:
        try:
            logger.info("Connecting to Discord gateway...")
            async with websockets.connect(self.config.gateway_url) as ws:
                self._ws = ws
                await self._gateway_loop()
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.warning("Discord gateway error: {}", e)
            if self._running:
                logger.info("Reconnecting to Discord gateway in 5 seconds...")
                await asyncio.sleep(5)

async def send(self, msg: OutboundMessage) -> None:
    """Send a message through Discord REST API, including file attachments."""
    if not self._http:
        logger.warning("Discord HTTP client not initialized")
        return

    url = f"{DISCORD_API_BASE}/channels/{msg.chat_id}/messages"
    headers = {"Authorization": f"Bot {self.config.token}"}

    try:
        sent_media = False
        failed_media: list[str] = []

        # Send file attachments first
        for media_path in msg.media or []:
            if await self._send_file(url, headers, media_path, reply_to=msg.reply_to):
                sent_media = True
            else:
                failed_media.append(Path(media_path).name)

        # Send text content
        chunks = split_message(msg.content or "", MAX_MESSAGE_LEN)
        if not chunks and failed_media and not sent_media:
            chunks = split_message(
                "\n".join(f"[attachment: {name} - send failed]" for name in failed_media),
                MAX_MESSAGE_LEN,
            )
        if not chunks:
            return

        for i, chunk in enumerate(chunks):
            payload: dict[str, Any] = {"content": chunk}

            # Let the first successful attachment carry the reply if present.
            if i == 0 and msg.reply_to and not sent_media:
                payload["message_reference"] = {"message_id": msg.reply_to}
                payload["allowed_mentions"] = {"replied_user": False}

            if not await self._send_payload(url, headers, payload):
                break  # Abort remaining chunks on failure
    finally:
        await self._stop_typing(msg.chat_id)

async def _send_payload(
    self, url: str, headers: dict[str, str], payload: dict[str, Any]
) -> bool:
    """Send a single Discord API payload with retry on rate-limit. Returns True on success."""
    for attempt in range(3):
        try:
            response = await self._http.post(url, headers=headers, json=payload)
            if response.status_code == 429:
                data = response.json()
                retry_after = float(data.get("retry_after", 1.0))
                logger.warning("Discord rate limited, retrying in {}s", retry_after)
                await asyncio.sleep(retry_after)
                continue
            response.raise_for_status()
            return True
        except Exception as e:
            if attempt == 2:
                logger.error("Error sending Discord message: {}", e)
            else:
                await asyncio.sleep(1)
    return False

async def _send_file(
    self,
    url: str,
    headers: dict[str, str],
    file_path: str,
    reply_to: str | None = None,
) -> bool:
    """Send a file attachment via Discord REST API using multipart/form-data."""
    path = Path(file_path)
    if not path.is_file():
        logger.warning("Discord file not found, skipping: {}", file_path)
        return False

    if path.stat().st_size > MAX_ATTACHMENT_BYTES:
        logger.warning("Discord file too large (>20MB), skipping: {}", path.name)
        return False

    payload_json: dict[str, Any] = {}
    if reply_to:
        payload_json["message_reference"] = {"message_id": reply_to}
        payload_json["allowed_mentions"] = {"replied_user": False}

    for attempt in range(3):
        try:
            with open(path, "rb") as f:
                files = {"files[0]": (path.name, f, "application/octet-stream")}
                data: dict[str, Any] = {}
                if payload_json:
                    data["payload_json"] = json.dumps(payload_json)
                response = await self._http.post(
                    url, headers=headers, files=files, data=data
                )
            if response.status_code == 429:
                resp_data = response.json()
                retry_after = float(resp_data.get("retry_after", 1.0))
                logger.warning("Discord rate limited, retrying in {}s", retry_after)
                await asyncio.sleep(retry_after)
                continue
            response.raise_for_status()
            logger.info("Discord file sent: {}", path.name)
            return True
        except Exception as e:
            if attempt == 2:
                logger.error("Error sending Discord file {}: {}", path.name, e)
