async def _read_media_bytes(
    self,
    media_ref: str,
) -> tuple[bytes | None, str | None, str | None]:
    if not media_ref:
        return None, None, None

    if self._is_http_url(media_ref):
        if not self._http:
            return None, None, None
        try:
            resp = await self._http.get(media_ref, follow_redirects=True)
            if resp.status_code >= 400:
                logger.warning(
                    "DingTalk media download failed status={} ref={}",
                    resp.status_code,
                    media_ref,
                )
                return None, None, None
            content_type = (resp.headers.get("content-type") or "").split(";")[0].strip()
            filename = self._guess_filename(media_ref, self._guess_upload_type(media_ref))
            return resp.content, filename, content_type or None
        except Exception as e:
            logger.error("DingTalk media download error ref={} err={}", media_ref, e)
            return None, None, None

    try:
        if media_ref.startswith("file://"):
            parsed = urlparse(media_ref)
            local_path = Path(unquote(parsed.path))
        else:
            local_path = Path(os.path.expanduser(media_ref))
        if not local_path.is_file():
            logger.warning("DingTalk media file not found: {}", local_path)
            return None, None, None
        data = await asyncio.to_thread(local_path.read_bytes)
        content_type = mimetypes.guess_type(local_path.name)[0]
        return data, local_path.name, content_type
    except Exception as e:
        logger.error("DingTalk media read error ref={} err={}", media_ref, e)
        return None, None, None

async def _upload_media(
    self,
    token: str,
    data: bytes,
    media_type: str,
    filename: str,
    content_type: str | None,
) -> str | None:
    if not self._http:
        return None
    url = f"https://oapi.dingtalk.com/media/upload?access_token={token}&type={media_type}"
    mime = content_type or mimetypes.guess_type(filename)[0] or "application/octet-stream"
    files = {"media": (filename, data, mime)}

    try:
        resp = await self._http.post(url, files=files)
        text = resp.text
        result = resp.json() if resp.headers.get("content-type", "").startswith("application/json") else {}
        if resp.status_code >= 400:
            logger.error("DingTalk media upload failed status={} type={} body={}", resp.status_code, media_type, text[:500])
            return None
        errcode = result.get("errcode", 0)
        if errcode != 0:
            logger.error("DingTalk media upload api error type={} errcode={} body={}", media_type, errcode, text[:500])
            return None
        sub = result.get("result") or {}
        media_id = result.get("media_id") or result.get("mediaId") or sub.get("media_id") or sub.get("mediaId")
        if not media_id:
            logger.error("DingTalk media upload missing media_id body={}", text[:500])
            return None
        return str(media_id)
    except Exception as e:
        logger.error("DingTalk media upload error type={} err={}", media_type, e)
        return None

async def _send_batch_message(
    self,
    token: str,
    chat_id: str,
    msg_key: str,
    msg_param: dict[str, Any],
) -> bool:
    if not self._http:
        logger.warning("DingTalk HTTP client not initialized, cannot send")
        return False

    headers = {"x-acs-dingtalk-access-token": token}
    if chat_id.startswith("group:"):
        # Group chat
        url = "https://api.dingtalk.com/v1.0/robot/groupMessages/send"
        payload = {
            "robotCode": self.config.client_id,
            "openConversationId": chat_id[6:],  # Remove "group:" prefix,
            "msgKey": msg_key,
            "msgParam": json.dumps(msg_param, ensure_ascii=False),
        }
    else:
        # Private chat
        url = "https://api.dingtalk.com/v1.0/robot/oToMessages/batchSend"
        payload = {
            "robotCode": self.config.client_id,
            "userIds": [chat_id],
            "msgKey": msg_key,
            "msgParam": json.dumps(msg_param, ensure_ascii=False),
        }

    try:
        resp = await self._http.post(url, json=payload, headers=headers)
        body = resp.text
        if resp.status_code != 200:
            logger.error("DingTalk send failed msgKey={} status={} body={}", msg_key, resp.status_code, body[:500])
            return False
        try: result = resp.json()
        except Exception: result = {}
        errcode = result.get("errcode")
        if errcode not in (None, 0):
            logger.error("DingTalk send api error msgKey={} errcode={} body={}", msg_key, errcode, body[:500])
            return False
        logger.debug("DingTalk message sent to {} with msgKey={}", chat_id, msg_key)
        return True
    except Exception as e:
        logger.error("Error sending DingTalk message msgKey={} err={}", msg_key, e)
        return False

