def _parse_md_table(cls, table_text: str) -> dict | None:
    """Parse a markdown table into a Feishu table element."""
    lines = [_line.strip() for _line in table_text.strip().split("\n") if _line.strip()]
    if len(lines) < 3:
        return None
    def split(_line: str) -> list[str]:
        return [c.strip() for c in _line.strip("|").split("|")]
    headers = [cls._strip_md_formatting(h) for h in split(lines[0])]
    rows = [[cls._strip_md_formatting(c) for c in split(_line)] for _line in lines[2:]]
    columns = [{"tag": "column", "name": f"c{i}", "display_name": h, "width": "auto"}
               for i, h in enumerate(headers)]
    return {
        "tag": "table",
        "page_size": len(rows) + 1,
        "columns": columns,
        "rows": [{f"c{i}": r[i] if i < len(r) else "" for i in range(len(headers))} for r in rows],
    }

def _build_card_elements(self, content: str) -> list[dict]:
    """Split content into div/markdown + table elements for Feishu card."""
    elements, last_end = [], 0
    for m in self._TABLE_RE.finditer(content):
        before = content[last_end:m.start()]
        if before.strip():
            elements.extend(self._split_headings(before))
        elements.append(self._parse_md_table(m.group(1)) or {"tag": "markdown", "content": m.group(1)})
        last_end = m.end()
    remaining = content[last_end:]
    if remaining.strip():
        elements.extend(self._split_headings(remaining))
    return elements or [{"tag": "markdown", "content": content}]

def _split_elements_by_table_limit(elements: list[dict], max_tables: int = 1) -> list[list[dict]]:
    """Split card elements into groups with at most *max_tables* table elements each.

    Feishu cards have a hard limit of one table per card (API error 11310).
    When the rendered content contains multiple markdown tables each table is
    placed in a separate card message so every table reaches the user.
    """
    if not elements:
        return [[]]
    groups: list[list[dict]] = []
    current: list[dict] = []
    table_count = 0
    for el in elements:
        if el.get("tag") == "table":
            if table_count >= max_tables:
                if current:
                    groups.append(current)
                current = []
                table_count = 0
            current.append(el)
            table_count += 1
        else:
            current.append(el)
    if current:
        groups.append(current)
    return groups or [[]]

def _split_headings(self, content: str) -> list[dict]:
    """Split content by headings, converting headings to div elements."""
    protected = content
    code_blocks = []
    for m in self._CODE_BLOCK_RE.finditer(content):
        code_blocks.append(m.group(1))
        protected = protected.replace(m.group(1), f"\x00CODE{len(code_blocks)-1}\x00", 1)

    elements = []
    last_end = 0
    for m in self._HEADING_RE.finditer(protected):
        before = protected[last_end:m.start()].strip()
        if before:
            elements.append({"tag": "markdown", "content": before})
        text = self._strip_md_formatting(m.group(2).strip())
        display_text = f"**{text}**" if text else ""
        elements.append({
            "tag": "div",
            "text": {
                "tag": "lark_md",
                "content": display_text,
            },
        })
        last_end = m.end()
    remaining = protected[last_end:].strip()
    if remaining:
        elements.append({"tag": "markdown", "content": remaining})

    for i, cb in enumerate(code_blocks):
        for el in elements:
            if el.get("tag") == "markdown":
                el["content"] = el["content"].replace(f"\x00CODE{i}\x00", cb)

    return elements or [{"tag": "markdown", "content": content}]

