def _format_tool_hint_lines(tool_hint: str) -> str:
    """Split tool hints across lines on top-level call separators only."""
    parts: list[str] = []
    buf: list[str] = []
    depth = 0
    in_string = False
    quote_char = ""
    escaped = False

    for i, ch in enumerate(tool_hint):
        buf.append(ch)

        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == quote_char:
                in_string = False
            continue

        if ch in {'"', "'"}:
            in_string = True
            quote_char = ch
            continue

        if ch == "(":
            depth += 1
            continue

        if ch == ")" and depth > 0:
            depth -= 1
            continue

        if ch == "," and depth == 0:
            next_char = tool_hint[i + 1] if i + 1 < len(tool_hint) else ""
            if next_char == " ":
                parts.append("".join(buf).rstrip())
                buf = []

    if buf:
        parts.append("".join(buf).strip())

    return "\n".join(part for part in parts if part)

